-- Sole definizioni delle colonne, nessuna riga di produzione.
CREATE TABLE public.marketing_contact_notes (
"id" uuid,
"contact_id" uuid,
"company_id" uuid,
"content" text,
"created_by" uuid,
"created_at" timestamp with time zone,
"opportunity_id" uuid,
"updated_at" timestamp with time zone,
"updated_by" uuid,
"automatica" boolean
);
CREATE TABLE public.marketing_documents (
"id" uuid,
"contact_id" uuid,
"opportunity_id" uuid,
"company_id" uuid,
"file_name" text,
"file_url" text,
"file_type" text,
"file_size" integer,
"uploaded_by" uuid,
"created_at" timestamp with time zone,
"categoria" text
);
CREATE TABLE public.tasks (
"id" uuid,
"company_id" uuid,
"title" text,
"notes" text,
"status" text,
"priority" text,
"due_date" date,
"assigned_to" uuid,
"order_id" uuid,
"stock_item_id" uuid,
"cost_id" uuid,
"category" text,
"created_by" uuid,
"completed_at" timestamp with time zone,
"created_at" timestamp with time zone,
"updated_at" timestamp with time zone,
"contact_id" uuid,
"opportunity_id" uuid,
"ticket_id" uuid,
"is_recurring" boolean,
"recurrence_rule" text,
"recurrence_end_date" date,
"parent_task_id" uuid,
"estimated_hours" numeric(4,1),
"sort_order" integer,
"actual_hours" numeric(8,2),
"bloccata_da_task_id" uuid,
"sblocco_giorni" smallint,
"ufficio_id" uuid,
"chiudi_su_evento" text,
"evento_gia_avvenuto" boolean,
"fase_al_completamento_id" uuid,
"acceptance_report_id" uuid,
"acceptance_action_index" integer
);
